export const renderCudaTritonKernelsDetailed: RichRenderFn = (g, _params, _meta, _graph) => {
  const totalW = 800;
  const cx = totalW / 2;
  let y = 30;

  drawLabel(g, cx, y, 'CUDA / Triton Kernels', { size: 16, weight: '700' });
  y += 22;
  drawLabel(g, cx, y, 'GPU Memory Hierarchy & Kernel Execution Model', { size: 10, color: '#888' });
  y += 28;

  drawTensor(g, cx - 130, y, 260, 30, 'input tensors on GPU (HBM)', '#fff3e0', '#e65100');
  y += 48;

  drawArrow(g, cx, y - 12, cx, y);
  y += 8;

  const hierX = cx - 320;
  const hierW = 640;
  const layers = [
    { label: 'Global Memory (HBM)', size: '40–80 GB', bw: '~1.5 TB/s', color: '#e65100', fill: '#fff3e0', h: 55 },
    { label: 'L2 Cache', size: '40–80 MB', bw: '~4 TB/s', color: '#f57c00', fill: '#ffe0b2', h: 45 },
    { label: 'L1 / Shared Memory (SRAM)', size: '48–228 KB / SM', bw: '~19 TB/s', color: '#1565c0', fill: '#e3f2fd', h: 55 },
    { label: 'Registers', size: '255 / thread', bw: '~80 TB/s', color: '#7b1fa2', fill: '#f3e5f5', h: 45 },
  ];

  drawLabel(g, hierX, y, 'GPU Memory Hierarchy', { size: 12, weight: '700', color: '#333', anchor: 'start' });
  y += 18;

  const inset = 30;
  layers.forEach((layer, i) => {
    const lx = hierX + i * inset;
    const lw = hierW - i * inset * 2;
    const lg = g.append('g').attr('transform', `translate(${lx}, ${y})`);

    lg.append('rect')
      .attr('width', lw).attr('height', layer.h).attr('rx', 6)
      .attr('fill', layer.fill).attr('stroke', layer.color).attr('stroke-width', 1.5);

    drawLabel(lg as unknown as Sel, lw / 2, layer.h / 2 - 8, layer.label, {
      size: 12, weight: '700', color: layer.color,
    });
    drawLabel(lg as unknown as Sel, lw / 2 - 60, layer.h / 2 + 10, layer.size, {
      size: 9, font: 'monospace', color: '#666',
    });
    drawLabel(lg as unknown as Sel, lw / 2 + 60, layer.h / 2 + 10, layer.bw, {
      size: 9, font: 'monospace', color: '#666',
    });

    if (i < layers.length - 1) {
      const arrowX = lx + lw / 2;
      drawArrow(g, arrowX, y + layer.h + 1, arrowX, y + layer.h + 12, { color: '#ccc' });
    }
    y += layer.h + 14;
  });
  y += 15;

  drawArrow(g, cx, y - 10, cx, y);
  y += 8;

  const execX = cx - 320;
  const execW = 640;
  drawLabel(g, execX, y, 'Kernel Execution Model', { size: 12, weight: '700', color: '#333', anchor: 'start' });
  y += 18;

  const gridG = g.append('g').attr('transform', `translate(${execX}, ${y})`);
  gridG.append('rect')
    .attr('width', execW).attr('height', 90).attr('rx', 6)
    .attr('fill', '#fafafa').attr('stroke', '#999').attr('stroke-width', 1).attr('stroke-dasharray', '4,2');
  drawLabel(gridG as unknown as Sel, 8, 12, 'Grid', { size: 9, weight: '700', color: '#999', anchor: 'start' });

  const blockW = 170;
  const blockH = 58;
  const blockGap = 20;
  const blockStartX = (execW - 3 * blockW - 2 * blockGap) / 2;
  for (let b = 0; b < 3; b++) {
    const bx = blockStartX + b * (blockW + blockGap);
    const bg = gridG.append('g').attr('transform', `translate(${bx}, 24)`);
    bg.append('rect')
      .attr('width', blockW).attr('height', blockH).attr('rx', 4)
      .attr('fill', '#e8f5e9').attr('stroke', '#4caf50').attr('stroke-width', 1.5);
    drawLabel(bg as unknown as Sel, blockW / 2, 12, `Block ${b}`, { size: 10, weight: '600', color: '#4caf50' });

    const threadW = 14;
    const threadH = 14;
    const threadGap = 2;
    const cols = 8;
    const rows2 = 2;
    const threadStartX = (blockW - cols * (threadW + threadGap)) / 2;
    for (let tr = 0; tr < rows2; tr++) {
      for (let tc = 0; tc < cols; tc++) {
        bg.append('rect')
          .attr('x', threadStartX + tc * (threadW + threadGap))
          .attr('y', 22 + tr * (threadH + threadGap))
          .attr('width', threadW).attr('height', threadH).attr('rx', 2)
          .attr('fill', '#fff').attr('stroke', '#4caf50').attr('stroke-width', 0.5);
      }
    }
    drawLabel(bg as unknown as Sel, blockW / 2, blockH - 6, 'threads (warps)', { size: 7, color: '#666' });

    if (b < 2) {
      drawLabel(gridG as unknown as Sel, bx + blockW + blockGap / 2, 50, '...', { size: 14, color: '#999' });
    }
  }
  y += 100;

  drawArrow(g, cx, y - 8, cx, y + 4);
  y += 12;

  const tileX = cx - 320;
  drawLabel(g, tileX, y, 'Tiling Strategy: Shared Memory Reuse', { size: 12, weight: '700', color: '#333', anchor: 'start' });
  y += 18;

  const tileSize = 40;
  const tileCols = 6;
  const tileRows = 3;

  drawLabel(g, tileX + 60, y, 'HBM (slow)', { size: 9, weight: '600', color: '#e65100', anchor: 'start' });
  const hbmG = g.append('g').attr('transform', `translate(${tileX + 20}, ${y + 8})`);
  for (let r = 0; r < tileRows; r++) {
    for (let c = 0; c < tileCols; c++) {
      hbmG.append('rect')
        .attr('x', c * (tileSize + 2)).attr('y', r * (tileSize + 2))
        .attr('width', tileSize).attr('height', tileSize).attr('rx', 2)
        .attr('fill', '#fff3e0').attr('stroke', '#e65100').attr('stroke-width', 0.5);
    }
  }
  hbmG.append('rect')
    .attr('x', 1 * (tileSize + 2)).attr('y', 0).attr('width', tileSize * 2 + 2).attr('height', tileSize * 2 + 2)
    .attr('rx', 3).attr('fill', 'none').attr('stroke', '#1565c0').attr('stroke-width', 2).attr('stroke-dasharray', '4,2');
  drawLabel(hbmG as unknown as Sel, 2 * (tileSize + 2) + tileSize / 2, tileSize * 2 + 14, 'tile → shared mem', { size: 8, color: '#1565c0' });

  const arrowMidX = tileX + 20 + tileCols * (tileSize + 2) + 30;
  drawArrow(g, arrowMidX, y + 8 + tileRows * (tileSize + 2) / 2, arrowMidX + 30, y + 8 + tileRows * (tileSize + 2) / 2, { color: '#78909c', label: 'load tile' });

  const sramX = arrowMidX + 40;
  drawLabel(g, sramX, y, 'SRAM (fast)', { size: 9, weight: '600', color: '#1565c0', anchor: 'start' });
  const sramG = g.append('g').attr('transform', `translate(${sramX}, ${y + 8})`);
  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 2; c++) {
      sramG.append('rect')
        .attr('x', c * (tileSize + 4)).attr('y', r * (tileSize + 4))
        .attr('width', tileSize).attr('height', tileSize).attr('rx', 2)
        .attr('fill', '#bbdefb').attr('stroke', '#1565c0').attr('stroke-width', 1);
    }
  }
  drawLabel(sramG as unknown as Sel, tileSize + 2, tileSize * 2 + 14, 'register accumulate', { size: 8, color: '#7b1fa2' });

  y += tileRows * (tileSize + 2) + 30;

  drawArrow(g, cx, y - 8, cx, y + 4);
  y += 12;
  drawTensor(g, cx - 130, y, 260, 30, 'computed output tensors (HBM)', '#fff3e0', '#e65100');
  y += 48;

  y = drawExplanation(g, cx - 330, y, 660,
    'Triton provides Python-like syntax that compiles to efficient CUDA, lowering the barrier to writing custom GPU kernels. '
    + 'The key insight is that SRAM is ~10x faster than HBM, so tiling data into shared memory and reusing it across threads '
    + 'is the single most important optimization technique.',
    'insight',
  );
  y = drawExplanation(g, cx - 330, y, 660,
    'Key optimizations: memory coalescing (consecutive threads access consecutive addresses), shared memory tiling, '
    + 'warp-level primitives (__shfl, __ballot), avoiding bank conflicts (32 banks, 4-byte stride), and register reuse. '
    + 'Flash Attention achieves 2-4x speedup purely via better memory access patterns, not more FLOPs.',
    'perf',
  );

  y = drawCodeAnnotation(g, cx - 330, y, 660,
    'Triton Matmul Kernel — Core Pattern',
    [
      'Load tiles from HBM to SRAM, accumulate in registers, store back.',
      'Each program handles one output tile (BLOCK_M x BLOCK_N).',
    ],
    [
      '@triton.jit',
      'def matmul_kernel(A, B, C, M, N, K, BLOCK_M, BLOCK_N, BLOCK_K):',
      '  pid = tl.program_id(0)',
      '  # Offsets for this program’s output tile',
      '  rm = pid // (N / BLOCK_N) * BLOCK_M + tl.arange(0, BLOCK_M)',
      '  rn = pid % (N / BLOCK_N) * BLOCK_N + tl.arange(0, BLOCK_N)',
      '  acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)',
      '  for k in range(0, K, BLOCK_K):',
      '    rk = k + tl.arange(0, BLOCK_K)',
      '    a_tile = tl.load(A + rm[:, None] * K + rk[None, :])',
      '    b_tile = tl.load(B + rk[:, None] * N + rn[None, :])',
      '    acc += tl.dot(a_tile, b_tile)',
      '  tl.store(C + rm[:, None] * N + rn[None, :], acc)',
    ],
  );

  return { width: totalW, height: y + 20, steps: [] };
};
